package viewer

import (
	"path/filepath"
	"strings"
)

// detection is what the name and the content managed to say about a document.
//
// Declared separates "the name said JSON" from "the content started with a
// brace". Only the first is worth reporting a parse failure for: a Markdown
// file that happens to open with a tag is not a broken XML document, and
// telling the user it is would be noise about a file that is displaying fine.
type detection struct {
	Kind     Kind
	Declared bool
}

// extensionKinds are the extensions that decide, on their own, what a file is.
//
// A log, a YAML and a TOML are only ever recognised here or declared by their
// producer — never sniffed from the content. "This looks like a log" is not a
// decidable question, and neither is "this looks like YAML": the registry
// `provider` field is the precedent, declared and never inferred from the URL,
// so nothing depends on what happened to be seen first.
var extensionKinds = map[string]Kind{
	".json": KindJSON,
	".xml":  KindXML,
	".log":  KindLog,
	".yaml": KindYAML,
	".yml":  KindYAML,
	".toml": KindTOML,
}

// DetectKind is what a document is, judged by its name and then its content.
func DetectKind(name string, data []byte) Kind {
	return detect(name, data).Kind
}

func detect(name string, data []byte) detection {
	ext := strings.ToLower(filepath.Ext(name))
	if kind, ok := extensionKinds[ext]; ok {
		return detection{Kind: kind, Declared: true}
	}
	// Any other extension is taken at its word: a .md, a .go or a .txt is text,
	// and sniffing it would open a Markdown file as a tree the first time
	// someone started one with a tag.
	if ext != "" {
		return detection{Kind: KindPlain}
	}
	return detection{Kind: sniff(data)}
}

// leadingNoise is what may sit in front of a document's first real character:
// whitespace, and a byte-order mark an editor left behind. Without the mark in
// this set, a BOM would hide the very byte this function exists to read.
const leadingNoise = " \t\r\n\ufeff"

// sniff guesses at a file with no extension at all — a Dockerfile, a Makefile,
// a dump someone redirected into a name. It looks at the first meaningful byte
// and nothing else; a document that then fails to parse simply falls back to
// text, with no complaint, because nothing claimed it was structured.
//
// Only JSON and XML are guessed at, and only because a leading brace or tag is
// the whole of the question. YAML and TOML are never sniffed: a file opening
// with `---` is not thereby YAML, and `[section]` is a line of prose in half the
// files that contain one.
func sniff(data []byte) Kind {
	head := data
	if len(head) > sniffSize {
		head = head[:sniffSize]
	}
	trimmed := strings.TrimLeft(string(head), leadingNoise)
	switch {
	case strings.HasPrefix(trimmed, "{"), strings.HasPrefix(trimmed, "["):
		return KindJSON
	case strings.HasPrefix(trimmed, "<"):
		return KindXML
	default:
		return KindPlain
	}
}

package viewer

import (
	"github.com/alecthomas/chroma/v2"
	"github.com/alecthomas/chroma/v2/lexers"
)

// TokenClass is what a run of text is, for colouring purposes. It is a small
// closed set of this package's own rather than chroma's several hundred token
// types: the theme has to have an opinion about every one of them, and eight is
// a number a palette can carry.
type TokenClass int

const (
	ClassText TokenClass = iota
	ClassKey
	ClassString
	ClassNumber
	ClassLiteral // true, false, null
	ClassPunct
	ClassTag
	ClassAttr
	ClassComment
)

// Token is a run of text and what it is.
type Token struct {
	Class TokenClass
	Text  string

	// Match says the current search found this run. It is a second axis, not a
	// ninth class: Class is what the text *is*, and an occurrence inside a key is
	// still a key. Tokenize never sets it — MarkMatches does, after the filter.
	Match bool
}

// Tokenize splits text for highlighting.
//
// chroma is used as a **lexer and nothing else**. Its formatters write their own
// ANSI colour and reset sequences, and a reset inside a line ends the app
// background for everything after it on that line (Rule 115) — the terminal's
// own background then shows through to the right margin. Emitting classes and
// letting lipgloss paint them is what keeps the background under our control.
//
// The invariant every caller depends on: concatenating the tokens' text
// reproduces the input exactly. A lexer that dropped or added a byte would
// desynchronise the rendered lines from the document's real ones.
func Tokenize(kind Kind, text string) []Token {
	name := lexerName(kind)
	if name == "" {
		return []Token{{Class: ClassText, Text: text}}
	}
	lexer := lexers.Get(name)
	if lexer == nil {
		return []Token{{Class: ClassText, Text: text}}
	}
	iterator, err := lexer.Tokenise(nil, text)
	if err != nil {
		// A lexer that will not run is not worth a message: the document is
		// displayed uncoloured, which is what `c` would have done anyway.
		return []Token{{Class: ClassText, Text: text}}
	}

	raw := iterator.Tokens()
	out := make([]Token, 0, len(raw))
	for _, token := range raw {
		out = append(out, Token{Class: classOf(kind, token.Type), Text: token.Value})
	}
	return out
}

// lexerName is the chroma lexer for a kind, or "" for a kind that has none.
//
// A log has none deliberately: its colour comes from its level, one whole line
// at a time, which is a different question from what a token is.
func lexerName(kind Kind) string {
	switch kind {
	case KindJSON:
		return "json"
	case KindXML:
		return "xml"
	case KindYAML:
		return "yaml"
	case KindTOML:
		return "toml"
	default:
		return ""
	}
}

// classOf maps a chroma token type onto our palette.
//
// The mapping was read off the four lexers rather than guessed: chroma emits
// NameTag for a JSON object key *and* for an XML tag, which is why the kind is
// a parameter. Both happen to resolve to the same colour today; naming them
// apart is what lets a theme separate them later without this function being
// wrong in the meantime.
//
// The reading is what settled YAML and TOML too. YAML needed nothing: its keys
// come out as NameTag, its scalars as Literal, its `true`/`null` as
// KeywordConstant, all of which already landed somewhere sensible. TOML needed
// one line — every one of its keys, table headers included, comes out as
// NameOther, which fell through to ClassText and left a TOML document coloured
// everywhere except the thing worth colouring.
func classOf(kind Kind, t chroma.TokenType) TokenClass {
	switch t.Category() {
	case chroma.Comment:
		return ClassComment
	case chroma.Keyword:
		return ClassLiteral
	case chroma.Punctuation, chroma.Operator:
		return ClassPunct
	case chroma.Literal:
		if t.InSubCategory(chroma.LiteralNumber) {
			return ClassNumber
		}
		return ClassString
	case chroma.Name:
		switch t {
		case chroma.NameAttribute:
			return ClassAttr
		case chroma.NameTag:
			if kind == KindXML {
				return ClassTag
			}
			return ClassKey
		case chroma.NameOther:
			// "A name the lexer could not qualify further", which in TOML is
			// precisely a key. It is not guarded on the kind because neither the
			// JSON nor the XML lexer emits it — TestJSONTokensAreClassified and
			// TestXMLTagsAndAttributesAreClassifiedApart are what keep that true,
			// and `if kind == KindTOML` is the one-line fallback if it stops being.
			return ClassKey
		default:
			return ClassText
		}
	default:
		return ClassText
	}
}

package viewer

import (
	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/viewport"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/viewer"
)

// display is how the document is shown. Two values, not three: "plain text" is
// this pane with the colour off, and giving it a display of its own would make
// one screen reachable two ways — the shape §3.9 removed from the secret
// backend and the deleted `:theme` command.
type display int

const (
	displayTree display = iota
	displayText
)

// Model is the document viewer.
type Model struct {
	config *config.Config
	width  int
	height int

	// source is where the document came from, and it is kept rather than
	// discarded after the first read: reload, follow and the timestamps toggle
	// are all questions for the origin, not for the bytes.
	source  viewer.Source
	doc     viewer.Document
	loading bool
	// spinner turns while the document is being read. The load is reported in
	// the footer, so the pane keeps whatever it was already showing.
	spinner spinner.Model

	display   display
	highlight bool
	wrap      bool
	minLevel  viewer.Level
	// showTimestamps is tracked here rather than asked of the source:
	// WithTimestamps returns a new source instead of mutating one, so nothing is
	// shared with a command already in flight (Rule 110), and there is therefore
	// nothing to read the flag back off.
	showTimestamps bool

	// The tree half.
	tree      datatable.Model[treeRow]
	collapsed map[int]bool

	// The text half. lines is the document cut into token spans; it is rebuilt
	// when the document loads and when `c` toggles, never per frame.
	lines        []docLine
	textViewport viewport.Model
	bar          components.FilterBar
	matchedLines int

	// OriginView is where esc returns to. The router sets it from whatever view
	// asked for the document.
	OriginView command.ViewType

	footer components.FooterMessage
}

// New builds an empty viewer.
//
// It exists so the router can create the view like any other — the contract test
// builds every view and asks it for a title and its shortcuts. On screen it says
// there is nothing open, which is the truth and is only ever reached by opening
// the view without a document.
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	return Model{
		spinner:      s,
		config:       cfg,
		highlight:    true,
		collapsed:    make(map[int]bool),
		tree:         datatable.New(datatable.Config[treeRow]{Columns: treeColumns(), SortColumn: -1}),
		textViewport: viewport.New(0, 0),
		bar:          components.NewFilterBar(),
		display:      displayText,
	}
}

// NewWithSource builds a viewer that will load this source when it starts.
func NewWithSource(cfg *config.Config, source viewer.Source) Model {
	m := New(cfg)
	m.source = source
	m.loading = true
	return m
}

// Name is what the header calls the document.
func (m Model) Name() string {
	if m.doc.Name != "" {
		return m.doc.Name
	}
	if m.source != nil {
		return m.source.Name()
	}
	return ""
}

// hasDocument reports whether anything has been loaded. Most of the keys and
// every shortcut but esc are conditional on it (Rule 130).
func (m Model) hasDocument() bool {
	return m.doc.Name != "" || m.doc.Text != ""
}

// structured reports whether the tree display is available at all.
func (m Model) structured() bool {
	return m.doc.Kind.Structured() && m.doc.Root != nil
}

// isLog reports whether the verbosity filter applies.
func (m Model) isLog() bool { return m.doc.Kind == viewer.KindLog }

// applyDocument installs a freshly parsed document and settles every piece of
// state that depends on it.
//
// One function rather than a handful of assignments at the call sites: a
// document arrives from a first load, from a reload and from a timestamps
// toggle, and a display left pointing at a tree that the new document does not
// have would render an empty pane with nothing to say why.
//
// It returns the footer message's expiry timer, which the caller must pass on:
// a message set without one never clears (Rule 128).
func (m *Model) applyDocument(doc viewer.Document) tea.Cmd {
	m.doc = doc
	m.loading = false
	m.collapsed = make(map[int]bool)
	m.lines = buildLines(doc, m.highlight)

	// A structured document opens on its tree, which is what the request asked
	// for: a .json opens as json, a .xml as xml. Everything else has no tree to
	// open on.
	if m.structured() {
		m.display = displayTree
	} else {
		m.display = displayText
	}

	// A verbosity filter left over from a previous document would hide lines of
	// this one for a reason the user set on something else.
	if !m.isLog() {
		m.minLevel = viewer.LevelUnknown
	}
	m.syncVerbosityToken()

	m.rebuildTree()
	m.tree.GotoTop()
	m.rebuildText()
	m.textViewport.GotoTop()

	// A warning, not an error: nothing failed, the document simply cannot be
	// shown the way its name asked for.
	if doc.ParseErr != nil {
		return m.footer.Warn("Malformed " + doc.Name + " — showing text")
	}
	return nil
}

// toggleHighlight is `c`. It rebuilds the spans, which is the one thing that
// costs anything here — and the reason it is a key rather than something
// recomputed on every frame.
func (m *Model) toggleHighlight() {
	m.highlight = !m.highlight
	m.lines = buildLines(m.doc, m.highlight)
	m.rebuildTree()
	m.rebuildText()
}

// toggleDisplay is `f`. It does nothing for a document with no tree, and the
// shortcut is hidden in that case rather than offered and ignored.
func (m *Model) toggleDisplay() {
	if !m.structured() {
		return
	}
	if m.display == displayTree {
		m.display = displayText
		return
	}
	m.display = displayTree
}

// formatLabel is what the header prints: the kind and the display, and the
// filter when there is one.
func (m Model) formatLabel() string {
	if !m.hasDocument() {
		return "-"
	}
	label := m.doc.Kind.String()
	if m.structured() {
		if m.display == displayTree {
			return label + " · tree"
		}
		return label + " · text"
	}
	if m.isLog() && m.minLevel != viewer.LevelUnknown {
		return label + " · " + minLevelLabel(m.minLevel)
	}
	return label
}

package viewer

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/viewer"
)

// docLine is one source line, kept as the token spans it is made of.
//
// The spans are the point. Wrapping counts runes, and an ANSI escape's bytes
// count as width — the same hazard Rule 122 describes for table cells — so a
// line that has already been coloured cannot be wrapped without the cut landing
// inside an escape sequence. Keeping the line as tokens means it is wrapped
// while it is still plain and coloured afterwards, which is the only order that
// works.
type docLine struct {
	Tokens []viewer.Token
	Plain  string
	Level  viewer.Level
}

// buildLines splits a document into styled-per-line spans.
//
// It is called when the document loads and when `c` toggles, and not otherwise:
// tokenising five megabytes per frame is not viable, and the filter and the
// wrap both work on the result rather than redoing it.
func buildLines(doc viewer.Document, highlight bool) []docLine {
	tokens := []viewer.Token{{Class: viewer.ClassText, Text: doc.Text}}
	if highlight {
		tokens = viewer.Tokenize(doc.Kind, doc.Text)
	}

	lines := splitTokenLines(tokens)

	// A log's level rides on the line, not on a token. The two lists are the
	// same split of the same text — ParseLog and splitTokenLines both cut on
	// "\n" — so they line up index for index.
	for i := range lines {
		if i < len(doc.Lines) {
			lines[i].Level = doc.Lines[i].Level
		}
	}
	return lines
}

// withText is a piece of a token: everything the run said about itself, over a
// shorter span of text.
//
// It is a copy rather than a fresh literal on purpose. Both of the functions
// below cut tokens up, and a literal has to name every field to keep it — which
// is how a highlight ends up working right until the line is long enough to be
// wrapped, the one case it exists for. Copying makes the omission unexpressible
// instead of something to remember for the next field anyone adds.
func withText(token viewer.Token, text string) viewer.Token {
	token.Text = text
	return token
}

// splitTokenLines cuts a document-wide token stream into one slice of tokens per
// line, splitting any token that spans a newline.
func splitTokenLines(tokens []viewer.Token) []docLine {
	var lines []docLine
	var current []viewer.Token
	var plain strings.Builder

	flush := func() {
		lines = append(lines, docLine{Tokens: current, Plain: plain.String()})
		current = nil
		plain.Reset()
	}

	for _, token := range tokens {
		parts := strings.Split(token.Text, "\n")
		for i, part := range parts {
			if i > 0 {
				flush()
			}
			if part == "" {
				continue
			}
			current = append(current, withText(token, part))
			plain.WriteString(part)
		}
	}
	flush()

	// A document ending in a newline produces a trailing empty line, which is
	// true of the text but renders as a blank row nobody asked for.
	if n := len(lines); n > 1 && lines[n-1].Plain == "" {
		lines = lines[:n-1]
	}
	return lines
}

// wrapTokens splits a line into segments no wider than width runes, cutting
// tokens where a segment ends.
//
// It breaks at the width rather than at a word boundary, for the same reason
// viewer.WrapLines does: the content here is a log line, a stack trace or a
// minified document, where the columns carry meaning.
func wrapTokens(tokens []viewer.Token, width int) [][]viewer.Token {
	if width <= 0 {
		return [][]viewer.Token{tokens}
	}

	var segments [][]viewer.Token
	var current []viewer.Token
	room := width

	for _, token := range tokens {
		runes := []rune(token.Text)
		for len(runes) > 0 {
			if room == 0 {
				segments = append(segments, current)
				current, room = nil, width
			}
			take := min(room, len(runes))
			current = append(current, withText(token, string(runes[:take])))
			runes = runes[take:]
			room -= take
		}
	}
	return append(segments, current)
}

// renderSegment paints a segment, one run at a time.
//
// A log line still reads as one piece — its level styles every run of it, so an
// ERROR is picked out at a glance, and a log has exactly one token per line
// unless a search cut it. That is the deliberate exception: an occurrence takes
// matchStyle even inside a log line, so the line comes out as level, match,
// level. A search that could not be seen in a log would be missing precisely
// where the lines are longest.
//
// Anything else is coloured by token class, with a match overriding it the same
// way.
func renderSegment(tokens []viewer.Token, level viewer.Level, isLog bool) string {
	var out strings.Builder
	for _, token := range tokens {
		out.WriteString(runStyle(token, level, isLog).Render(token.Text))
	}
	return out.String()
}

func runStyle(token viewer.Token, level viewer.Level, isLog bool) lipgloss.Style {
	switch {
	case token.Match:
		return matchStyle()
	case isLog:
		return levelStyle(level)
	default:
		return syntaxStyle(token.Class)
	}
}

package viewer

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders whichever half is on screen.
func (m Model) View() string {
	contentStyle := lipgloss.NewStyle().Background(theme.ColorBackground).PaddingLeft(1)

	switch {
	case m.loading && !m.hasDocument():
		// The load says so in the footer, with a spinner. Nothing is shown here
		// because there is nothing yet to show — and a reload keeps the
		// document on screen rather than blanking it, which is the case below.
		return ""
	case !m.hasDocument():
		return contentStyle.Render(theme.HelpStyle.Render("\nNothing open\n\nOpen a file from workspaces, or inspect a container."))
	case m.display == displayTree:
		return m.tree.View()
	default:
		return m.textViewport.View()
	}
}

// GetFooterHeight is Rule 124's budget: an empty line and an info line, plus the
// filter bar when it is showing.
func (m Model) GetFooterHeight() int {
	return 2 + m.bar.ExtraHeight()
}

// RenderFooter draws the filter bar and the one line of state.
func (m Model) RenderFooter(width int) string {
	var parts []string
	if m.bar.IsVisible() {
		parts = append(parts, m.bar.View())
	}
	parts = append(parts, theme.EmptyLineBg(width), m.footer.View(width, m.status()))
	return strings.Join(parts, "\n")
}

// status is what the view derives on every frame: the read, reported here so
// the pane does not swap itself for a message.
func (m Model) status() components.Status {
	if m.loading {
		return components.Status{Text: "Loading " + m.Name() + "...", Spinner: true}
	}
	return components.Status{}
}

// ── HeaderView ───────────────────────────────────────────────────────────────
//
// All four methods. The router probes for the interface as a whole and falls
// back in silence, so a view supplying two of them renders an empty title with
// nothing to say why — which is what happened to the configuration view.

func (m Model) GetTitle() string {
	if name := m.Name(); name != "" {
		return theme.IconCodeFile + " Viewer · " + name
	}
	return theme.IconCodeFile + " Viewer"
}

func (m Model) GetIcon() string { return "" }

func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
		{Key: "Format", Value: m.formatLabel(), Style: theme.HeaderValueStyle},
	}
	if !m.hasDocument() {
		return info
	}
	if m.structured() && m.display == displayTree {
		return append(info, shortcut.HeaderInfo{
			Key: "Nodes", Value: fmt.Sprintf("%d", m.doc.NodeCount()), Style: theme.HeaderValueStyle,
		})
	}
	return append(info, shortcut.HeaderInfo{
		Key: "Lines", Value: m.lineCount(), Style: theme.HeaderValueStyle,
	})
}

// lineCount says how many lines are showing, and out of how many when a filter
// is narrowing them. A bare count under an active filter would read as the size
// of the document, which is the one thing it is not.
func (m Model) lineCount() string {
	total := len(m.lines)
	if m.matchedLines == total {
		return fmt.Sprintf("%d", total)
	}
	return fmt.Sprintf("%d/%d", m.matchedLines, total)
}

// GetShortcuts is state-aware (Rule 130): every key that depends on the kind of
// document or on what its source can do is offered only when it would work.
func (m Model) GetShortcuts() shortcut.Shortcuts {
	if !m.hasDocument() {
		return []shortcut.Shortcut{{Key: "esc", Description: "Go back"}}
	}

	var shortcuts []shortcut.Shortcut

	if m.structured() {
		if m.display == displayTree {
			shortcuts = append(shortcuts,
				shortcut.Shortcut{Key: "←→", Description: "Collapse/Expand"},
				shortcut.Shortcut{Key: "f", Description: "Show as text"},
			)
		} else {
			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "f", Description: "Show as tree"})
		}
	}

	if m.display == displayText {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "w", Description: "Toggle wrap"})
		if m.isLog() {
			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "v", Description: "Verbosity"})
		}
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "/", Description: "Search"})
	}

	shortcuts = append(shortcuts, shortcut.Shortcut{Key: "c", Description: "Toggle coloring"})

	if _, ok := m.timestamps(); ok {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "t", Description: "Toggle timestamps"})
	}
	if m.source != nil {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+r", Description: "Reload"})
	}
	if _, ok := m.followable(); ok {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "F", Description: "Follow live output"})
	}
	if _, ok := m.pageable(); ok {
		shortcuts = append(shortcuts, shortcut.Shortcut{Key: "V", Description: "Open in system pager"})
	}

	return append(shortcuts,
		shortcut.Shortcut{Key: "esc", Description: "Go back"},
		shortcut.Shortcut{Key: "?", Description: "Help"},
	)
}

// GetHelpContent implements help.Provider (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Viewer",
		Description: "A read-only view of one document. JSON and XML open on a navigable tree; " +
			"YAML and TOML open as colored text; logs open as text with a verbosity filter; " +
			"everything else opens as text. " +
			"The viewer is opened from another view — a file in workspaces, an inspect or a log in containers — and Esc returns there.",
		KeyBindings: []help.KeyBinding{
			{Key: "↑/k", Description: "Move up"},
			{Key: "↓/j", Description: "Move down"},
			{Key: "→/l", Description: "Expand the selected node (tree)"},
